def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            result.append(comp)
    return result

def normalized_shape(comp):
    r0 = min(r for r, c in comp)
    c0 = min(c for r, c in comp)
    return frozenset((r-r0, c-c0) for r, c in comp)

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    background = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    border_markers = []
    for color in colors - {background}:
        for comp in components(grid, color):
            rs = [r for r, c in comp]
            cs = [c for r, c in comp]
            touches = sum((min(rs) == 0, max(rs) == h-1, min(cs) == 0, max(cs) == w-1))
            if touches >= 2:
                border_markers.append((len(comp), color, comp))
    if not border_markers:
        return out
    _, paint, marker = max(border_markers)
    groups = {}
    for color in colors - {background, paint}:
        for comp in components(grid, color):
            groups.setdefault(normalized_shape(comp), []).append(comp)
    repeated = [(shape, comps) for shape, comps in groups.items() if len(comps) >= 2]
    if not repeated:
        return out
    shape, copies = max(repeated, key=lambda item: (len(item[0]), len(item[1])))
    def marker_distance(comp):
        return min(abs(r-y) + abs(c-x) for r, c in comp for y, x in marker)
    # The corner marker identifies which matching copy is selected: use the
    # congruent object furthest from the marker, i.e. toward its opposite side.
    chosen = max(copies, key=marker_distance)
    for r, c in chosen:
        out[r][c] = paint
    return out

